import{_ as r,c as t,o as l,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"卦と爻の構造","description":"卦と爻の構造，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"卦と爻の構造","description":"卦と爻の構造，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"ja/articles/structure/index.md","filePath":"ja/articles/structure/index.md"}'),e={name:"ja/articles/structure/index.md"};function n(o,a,s,d,h,g){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="八卦から六十四卦へ-上下卦・動静爻・互卦・之卦" tabindex="-1">八卦から六十四卦へ：上下卦・動静爻・互卦・之卦 <a class="header-anchor" href="#八卦から六十四卦へ-上下卦・動静爻・互卦・之卦" aria-label="Permalink to “八卦から六十四卦へ：上下卦・動静爻・互卦・之卦”">​</a></h1><p>八卦（三爻卦）は易の「基本単位」、六十四卦（六爻卦）はその「応用形」です。六十四卦は <strong>二つの三爻卦を上下に重ねる</strong> ことで構成され、さらに動爻によって之卦（変卦）が生まれ、互卦で中間の状況を読み分けます。</p><h2 id="_1-上下卦-六十四卦の骨格" tabindex="-1">1. 上下卦：六十四卦の骨格 <a class="header-anchor" href="#_1-上下卦-六十四卦の骨格" aria-label="Permalink to “1. 上下卦：六十四卦の骨格”">​</a></h2><p>六爻卦は「内卦（下卦）」と「外卦（上卦）」から成ります。</p><ul><li><strong>下卦（内）</strong>：初〜三爻。内側の状態、起点、主体。</li><li><strong>上卦（外）</strong>：四〜上爻。外側の条件、環境、展開。</li></ul><p>命名は基本的に「上卦（外）の象意 → 下卦（内）の象意」の順で呼びます（例：山水蒙、天水訟）。</p><p>数学的には 8 卦×8 卦＝64 通りで、主要な状況を網羅するように設計されています。</p><h2 id="_2-動静爻と之卦-変化の読み" tabindex="-1">2. 動静爻と之卦：変化の読み <a class="header-anchor" href="#_2-動静爻と之卦-変化の読み" aria-label="Permalink to “2. 動静爻と之卦：変化の読み”">​</a></h2><p>占筮では、少陰（8）・少陽（7）は静、老陰（6）・老陽（9）が動とされ、<strong>動爻だけが反転</strong>して之卦（変卦）を作ります。</p><ul><li>陽（—）が動く → 陰（--）へ</li><li>陰（--）が動く → 陽（—）へ</li></ul><p>読みの基本は次の通りです。</p><ul><li><strong>本卦</strong>：現状（体）</li><li><strong>之卦</strong>：傾向／調整（用）</li><li><strong>動爻の爻辞</strong>：転換点の具体（最重要）</li></ul><h2 id="_3-互卦-中間の状況を補う" tabindex="-1">3. 互卦：中間の状況を補う <a class="header-anchor" href="#_3-互卦-中間の状況を補う" aria-label="Permalink to “3. 互卦：中間の状況を補う”">​</a></h2><p>互卦は、本卦の中ほどの爻を取り出して作る「内面のサブストーリー」です。</p><ul><li><strong>下互卦</strong>：二・三・四爻</li><li><strong>上互卦</strong>：三・四・五爻</li></ul><p>本卦（起点）と之卦（行き先）の間にある「途中の条件・心理・隠れた流れ」を読み分ける補助になります。</p><h2 id="_4-まとめ" tabindex="-1">4. まとめ <a class="header-anchor" href="#_4-まとめ" aria-label="Permalink to “4. まとめ”">​</a></h2><p>六十四卦の理解は、次の三層を押さえると整理できます。</p><ol><li><strong>構造（上下卦）</strong>：骨格（状況の枠）。</li><li><strong>変化（動爻→之卦）</strong>：血流（展開の方向）。</li><li><strong>深化（互卦）</strong>：神経（中間の機微）。</li></ol><hr><h1 id="「爻」とは何か-卦をつくる最小単位" tabindex="-1">「爻」とは何か：卦をつくる最小単位 <a class="header-anchor" href="#「爻」とは何か-卦をつくる最小単位" aria-label="Permalink to “「爻」とは何か：卦をつくる最小単位”">​</a></h1><p>易の卦は、六本の<strong>爻（こう）</strong>を下から上へ積み重ねて表します。爻は文字の「画」や建築の「レンガ」のように、卦象を構成する最小単位です。単体では意味が薄くても、<strong>陰陽・動静・位置・関係</strong>を合わせて読むことで、具体的な示唆になります。</p><h2 id="_1-陰爻と陽爻" tabindex="-1">1. 陰爻と陽爻 <a class="header-anchor" href="#_1-陰爻と陽爻" aria-label="Permalink to “1. 陰爻と陽爻”">​</a></h2><ul><li><strong>陽爻（—）</strong>：剛健・能動・上昇。</li><li><strong>陰爻（--）</strong>：柔順・受動・下降。</li></ul><p>乾は純陽、坤は純陰で、他の卦は陰陽の混合によって状況の複雑さを表します。</p><h2 id="_2-静爻と動爻" tabindex="-1">2. 静爻と動爻 <a class="header-anchor" href="#_2-静爻と動爻" aria-label="Permalink to “2. 静爻と動爻”">​</a></h2><p>占筮では、爻が「変化するかどうか」が重要です。</p><ul><li><strong>静爻</strong>：陰陽が固定され、基本の状態を表す。</li><li><strong>動爻（変爻）</strong>：陰陽が反転し、之卦（変卦）を生む。転換点の手がかり。</li></ul><h2 id="_3-爻位-1〜6" tabindex="-1">3. 爻位（1〜6） <a class="header-anchor" href="#_3-爻位-1〜6" aria-label="Permalink to “3. 爻位（1〜6）”">​</a></h2><p>爻は下から順に、初・二・三・四・五・上（1〜6）と数えます。一般に、位置が上がるほど「段階が後」「役割が重い」と捉えます。</p><table tabindex="0"><thead><tr><th>番号</th><th>名称</th><th>象意（目安）</th></tr></thead><tbody><tr><td>1</td><td>初</td><td>始まり、基礎</td></tr><tr><td>2</td><td>二</td><td>支え、適中</td></tr><tr><td>3</td><td>三</td><td>変わり目、負荷</td></tr><tr><td>4</td><td>四</td><td>移行、調整</td></tr><tr><td>5</td><td>五</td><td>中心、主位</td></tr><tr><td>6</td><td>上</td><td>極まり、終局</td></tr></tbody></table><h2 id="_4-関係-応・比・乗・承" tabindex="-1">4. 関係（応・比・乗・承） <a class="header-anchor" href="#_4-関係-応・比・乗・承" aria-label="Permalink to “4. 関係（応・比・乗・承）”">​</a></h2><p>爻は単独ではなく、相互関係で読みます。</p><ul><li><strong>応</strong>：1↔4、2↔5、3↔6 の対応関係（内外の呼応）。</li><li><strong>比</strong>：隣り合う爻同士の影響（近い環境）。</li><li><strong>乗／承</strong>：上下関係としての「乗る」「支える」（流派・卦によって細部の用法は異なる）。</li></ul><hr><h1 id="爻位の読み-当位・不当位、応、乗承比" tabindex="-1">爻位の読み：当位・不当位、応、乗承比 <a class="header-anchor" href="#爻位の読み-当位・不当位、応、乗承比" aria-label="Permalink to “爻位の読み：当位・不当位、応、乗承比”">​</a></h1><p>同じ陰爻／陽爻でも、置かれる位置（爻位）によって意味が変わります。ここでは、六爻の「位置がもつ役割」を整理します。</p><h2 id="_1-当位-得位-と不当位-不得位" tabindex="-1">1. 当位（得位）と不当位（不得位） <a class="header-anchor" href="#_1-当位-得位-と不当位-不得位" aria-label="Permalink to “1. 当位（得位）と不当位（不得位）”">​</a></h2><p>六つの位置には「陰位／陽位」があります。</p><ul><li>1/3/5 は <strong>陽位</strong></li><li>2/4/6（上）は <strong>陰位</strong></li></ul><p>陽爻が陽位、陰爻が陰位にあると <strong>当位（得位）</strong> とされ、整いやすい。逆は <strong>不当位</strong> で、ズレや無理が出やすい、と整理します（必ず凶ではなく、問題提起として読む）。</p><h2 id="_2-応-内外の呼応" tabindex="-1">2. 応（内外の呼応） <a class="header-anchor" href="#_2-応-内外の呼応" aria-label="Permalink to “2. 応（内外の呼応）”">​</a></h2><ul><li>1↔4、2↔5、3↔6 が対応します。</li><li>陰陽が異なると調和しやすい、同じだと衝突しやすい、という読みが基本です。</li></ul><h2 id="_3-比-隣接の影響" tabindex="-1">3. 比（隣接の影響） <a class="header-anchor" href="#_3-比-隣接の影響" aria-label="Permalink to “3. 比（隣接の影響）”">​</a></h2><p>隣り合う爻（1-2、2-3…）は近い環境を表します。剛柔のバランスが取れているか、力が偏っていないかを見ます。</p><h2 id="_4-乗・承-上下関係" tabindex="-1">4. 乗・承（上下関係） <a class="header-anchor" href="#_4-乗・承-上下関係" aria-label="Permalink to “4. 乗・承（上下関係）”">​</a></h2><p>下の爻が上を支える／上の爻が下に乗る、という上下の力学として整理します。占筮では、動爻や主位（五）と組み合わせて、どこに負荷がかかっているかを読み分けます。</p><hr><h1 id="爻辞と象伝-大象・小象の読み方" tabindex="-1">爻辞と象伝：大象・小象の読み方 <a class="header-anchor" href="#爻辞と象伝-大象・小象の読み方" aria-label="Permalink to “爻辞と象伝：大象・小象の読み方”">​</a></h1><p>易のテキストには、卦辞・爻辞に加えて「象伝」があります。象伝は、卦象（形）から状況を比喩的に引き出し、行動の指針へつなげる文章です。</p><h2 id="_1-卦辞・爻辞・象伝の役割" tabindex="-1">1. 卦辞・爻辞・象伝の役割 <a class="header-anchor" href="#_1-卦辞・爻辞・象伝の役割" aria-label="Permalink to “1. 卦辞・爻辞・象伝の役割”">​</a></h2><ul><li><strong>卦辞</strong>：その卦全体のテーマ（大枠）。</li><li><strong>爻辞</strong>：段階ごとの具体（局面の細部）。</li><li><strong>象伝</strong>：象（イメージ）から理（教訓）を導く（比喩の橋渡し）。</li></ul><h2 id="_2-大象と小象" tabindex="-1">2. 大象と小象 <a class="header-anchor" href="#_2-大象と小象" aria-label="Permalink to “2. 大象と小象”">​</a></h2><ul><li><strong>大象</strong>：卦全体の象意（上下卦・自然現象）から、全体方針を述べる。</li><li><strong>小象</strong>：各爻の象意から、局面ごとの注意点を補う。</li></ul><h2 id="_3-読み方のコツ" tabindex="-1">3. 読み方のコツ <a class="header-anchor" href="#_3-読み方のコツ" aria-label="Permalink to “3. 読み方のコツ”">​</a></h2><ol><li>まず卦の上下卦（象）を言い換える（例：山＝止、水＝険）。</li><li>次に「今の状況にどう当てはまるか」を短く要約する。</li><li>最後に、卦辞→動爻の爻辞→象伝の順で整合を取る。</li></ol><p>象伝は「正解を当てる」ためではなく、状況を立体的に捉えるための助けになります。</p>',57)])])}const _=r(e,[["render",n]]);export{p as __pageData,_ as default};
